// HasLicenseKey applies the HasEdge predicate on the "license_key" edge.
func HasLicenseKey() predicate.User {
	return predicate.User(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, false, LicenseKeyTable, LicenseKeyColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasLicenseKeyWith applies the HasEdge predicate on the "license_key" edge with a given conditions (other predicates).
func HasLicenseKeyWith(preds ...predicate.LicenseKey) predicate.User {
	return predicate.User(func(s *sql.Selector) {
		step := newLicenseKeyStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

